def once(n): return ' Sólo puedes usar este efecto de "%s" una vez por turno.' % n
def u(target, extra='', atk=False):
    s = 'Una vez por turno, puedes: seleccionar 1 %s que controles; equipa esta carta a ese objetivo, O BIEN: desequipar esta carta e Invocarla de Modo Especial%s.' % (target, ' en Posición de Ataque' if atk else '')
    return s
